static Field[] indexLatLonPolygon(
    String fieldName, Polygon polygon, boolean checkSelfIntersections) {
  ShapeField coordinator = new ShapeField();
  coordinator.latLonFieldName = fieldName;
  coordinator.latLonPolygon = polygon;
  coordinator.latLonCheckSelfIntersections = checkSelfIntersections;
  coordinator.tessellateCurrentLatLonPolygon();
  return coordinator.fieldsFromCurrentLatLonTessellation();
}

