import org.apache.lucene.search.Query;
import org.apache.lucene.util.BytesRef;
import org.apache.lucene.util.NumericUtils;

/**
 * A base shape utility class used for both LatLon (spherical) and XY (cartesian) shape fields.
 *
 * <p>{@link Polygon}'s and {@link Line}'s are decomposed into a triangular mesh using the {@link
 * Tessellator} utility class. Each {@link Triangle} is encoded by this base class and indexed as a
 * seven dimension multi-value field.
 *
 * <p>Finding all shapes that intersect a range (e.g., bounding box), or target shape, at search
 * time is efficient.
 *
 * <p>This class defines the static methods for encoding the three vertices of a tessellated
 * triangles as a seven dimension point. The coordinates are converted from double precision values
 * into 32 bit integers so they are sortable at index time.
 */
public final class ShapeField {
  /** vertex coordinates are encoded as 4 byte integers */
  static final int BYTES = Integer.BYTES;

  /**
   * tessellated triangles are seven dimensions; the first four are the bounding box index
   * dimensions
   */
  protected static final FieldType TYPE = new FieldType();

  static {
    TYPE.setDimensions(7, 4, BYTES);
    TYPE.freeze();
  }

  // lat/lon indexing workspace
  private String latLonFieldName;
  private Polygon latLonPolygon;
  private Line latLonLine;
  private boolean latLonCheckSelfIntersections;
  private List<Tessellator.Triangle> latLonTessellation;
  private Field[] latLonFields;
  private List<DecodedTriangle> latLonDecodedTriangles;
  private double latLonPointLat;
  private double latLonPointLon;
  private byte[] latLonScratchBytes;

  // cartesian indexing workspace
  private String xyFieldName;
  private XYPolygon xyPolygon;
  private boolean xyCheckSelfIntersections;
  private List<Tessellator.Triangle> xyTessellation;
  private Field[] xyFields;
  private List<DecodedTriangle> xyDecodedTriangles;
  private float[] xyLineX;
  private float[] xyLineY;
  private float xyPointX;
  private float xyPointY;

  // query construction workspace
  private String queryFieldName;
  private QueryRelation activeQueryRelation;
  private LatLonGeometry[] latLonQueryGeometries;
  private XYGeometry[] xyQueryGeometries;
  private double queryMinLat;
  private double queryMaxLat;
  private double queryMinLon;
  private double queryMaxLon;
  private float queryMinX;
  private float queryMaxX;
  private float queryMinY;
  private float queryMaxY;

  // lat/lon spatial matching workspace
  private Component2D latLonMatchComponent;
  private DecodedTriangle latLonMatchTriangle;
  private double latLonMatchALat;
  private double latLonMatchALon;
  private double latLonMatchBLat;
  private double latLonMatchBLon;
  private double latLonMatchCLat;
  private double latLonMatchCLon;
  private double latLonRangeMinLat;
  private double latLonRangeMinLon;
  private double latLonRangeMaxLat;
  private double latLonRangeMaxLon;

  // cartesian spatial matching workspace
  private Component2D xyMatchComponent;
  private DecodedTriangle xyMatchTriangle;
  private double xyMatchAX;
  private double xyMatchAY;
  private double xyMatchBX;
  private double xyMatchBY;
  private double xyMatchCX;
  private double xyMatchCY;
  private double xyRangeMinX;
  private double xyRangeMinY;
  private double xyRangeMaxX;
  private double xyRangeMaxY;

  // short-lived workspaces are created internally for indexing and matching
  private ShapeField() {}

  /**
   * polygons are decomposed into tessellated triangles using {@link
   * org.apache.lucene.geo.Tessellator} these triangles are encoded and inserted as separate indexed
   * POINT fields
   */
  public static class Triangle extends Field {

    /** constructor for points and lines */
    Triangle(
        String name,
        int aXencoded,
        int aYencoded,
        int bXencoded,
        int bYencoded,
        int cXencoded,
        int cYencoded) {
      super(name, TYPE);
      setTriangleValue(
          aXencoded, aYencoded, true, bXencoded, bYencoded, true, cXencoded, cYencoded, true);
    }

    /** xtor from a given Tessellated Triangle object */
    Triangle(String name, Tessellator.Triangle t) {
      super(name, TYPE);
      setTriangleValue(
          t.getEncodedX(0),
          t.getEncodedY(0),
          t.isEdgefromPolygon(0),
          t.getEncodedX(1),
          t.getEncodedY(1),
          t.isEdgefromPolygon(1),
          t.getEncodedX(2),
          t.getEncodedY(2),
          t.isEdgefromPolygon(2));
    }

    /** sets the vertices of the triangle as integer encoded values */
    protected void setTriangleValue(
        int aX,
        int aY,
        boolean abFromShape,
        int bX,
        int bY,
        boolean bcFromShape,
        int cX,
        int cY,
        boolean caFromShape) {
      final byte[] bytes;

      if (fieldsData == null) {
        bytes = new byte[7 * BYTES];
        fieldsData = new BytesRef(bytes);
      } else {
        bytes = ((BytesRef) fieldsData).bytes;
      }
      encodeTriangle(bytes, aY, aX, abFromShape, bY, bX, bcFromShape, cY, cX, caFromShape);
    }
  }

  /** Query Relation Types * */
  public enum QueryRelation {
    /** used for INTERSECT Queries */
    INTERSECTS,
    /** used for WITHIN Queries */
    WITHIN,
    /** used for DISJOINT Queries */
    DISJOINT,
    /** used for CONTAINS Queries */
    CONTAINS
  }

  private static final int MINY_MINX_MAXY_MAXX_Y_X = 0;
  private static final int MINY_MINX_Y_X_MAXY_MAXX = 1;
  private static final int MAXY_MINX_Y_X_MINY_MAXX = 2;
  private static final int MAXY_MINX_MINY_MAXX_Y_X = 3;
  private static final int Y_MINX_MINY_X_MAXY_MAXX = 4;
  private static final int Y_MINX_MINY_MAXX_MAXY_X = 5;
  private static final int MAXY_MINX_MINY_X_Y_MAXX = 6;
  private static final int MINY_MINX_Y_MAXX_MAXY_X = 7;

  /**
   * A triangle is encoded using 6 points and an extra point with encoded information in three bits
   * of how to reconstruct it. Triangles are encoded with CCW orientation and might be rotated to
   * limit the number of possible reconstructions to 2^3. Reconstruction always happens from west to
   * east.
   */
  public static void encodeTriangle(
      byte[] bytes,
      int aY,
      int aX,
      boolean ab,
      int bY,
      int bX,
      boolean bc,
      int cY,
      int cX,
      boolean ca) {
