static SpatialQuery.SpatialVisitor createXYSpatialVisitor(Component2D component2D) {
  ShapeField matcher = new ShapeField();
  matcher.xyMatchComponent = component2D;
  matcher.xyMatchTriangle = new DecodedTriangle();
  return matcher.buildXYSpatialVisitor();
}

private SpatialQuery.SpatialVisitor buildXYSpatialVisitor() {
  return new SpatialQuery.SpatialVisitor() {
    @Override
    protected Relation relate(byte[] minTriangle, byte[] maxTriangle) {
      decodeXYRange(minTriangle, maxTriangle);
      return relateDecodedXYRange();
    }

    @Override
    protected Predicate<byte[]> intersects() {
      return triangle -> {
        decodeXYMatchTriangle(triangle);
        return xyMatchIntersects();
      };
    }

    @Override
    protected Predicate<byte[]> within() {
      return triangle -> {
        decodeXYMatchTriangle(triangle);
        return xyMatchWithin();
      };
    }

    @Override
    protected Function<byte[], Component2D.WithinRelation> contains() {
      return triangle -> {
        decodeXYMatchTriangle(triangle);
        return xyMatchContains();
      };
    }
  };
}

private void decodeXYRange(byte[] minTriangle, byte[] maxTriangle) {
  if (xyMatchComponent == null && xyMatchTriangle == null) {
    xyMatchTriangle = new DecodedTriangle();
  }
  xyRangeMinY = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(minTriangle, 0));
  xyRangeMinX = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(minTriangle, BYTES));
  xyRangeMaxY = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(maxTriangle, 2 * BYTES));
  xyRangeMaxX = XYEncodingUtils.decode(NumericUtils.sortableBytesToInt(maxTriangle, 3 * BYTES));
}

